using System.ComponentModel;
using System.Runtime.InteropServices;
using NexaStation.Core;
using NexaStation.Domain;

namespace NexaStation.DesktopControl.Input;

public sealed partial class DesktopInputInjector:IDesktopInputInjector
{
    public DesktopInputInjectionResult MoveCursor(double deltaX,double deltaY){if(!GetCursorPos(out POINT p))return Failure();int left=GetSystemMetrics(76),top=GetSystemMetrics(77),right=left+GetSystemMetrics(78)-1,bottom=top+GetSystemMetrics(79)-1;return SetCursorPos(Math.Clamp(p.X+(int)Math.Round(deltaX),left,right),Math.Clamp(p.Y+(int)Math.Round(deltaY),top,bottom))?new(true,"Cursor moved."):Failure();}
    public DesktopInputInjectionResult Scroll(int verticalDelta,int horizontalDelta){List<INPUT>inputs=[];if(verticalDelta!=0)inputs.Add(Mouse(0x0800,verticalDelta));if(horizontalDelta!=0)inputs.Add(Mouse(0x01000,horizontalDelta));return Send(inputs);}
    public DesktopInputInjectionResult Click(DesktopMouseButton button){(uint down,uint up)=button switch{DesktopMouseButton.Left=>(0x0002u,0x0004u),DesktopMouseButton.Right=>(0x0008u,0x0010u),_=>(0x0020u,0x0040u)};return Send([Mouse(down,0),Mouse(up,0)]);}
    public DesktopInputInjectionResult SendApprovedKey(DesktopApprovedKey key){(ushort code,bool extended)=key switch{DesktopApprovedKey.Escape=>((ushort)0x1B,false),DesktopApprovedKey.Enter=>((ushort)0x0D,false),DesktopApprovedKey.Space=>((ushort)0x20,false),DesktopApprovedKey.Tab=>((ushort)0x09,false),DesktopApprovedKey.Backspace=>((ushort)0x08,false),DesktopApprovedKey.Up=>((ushort)0x26,true),DesktopApprovedKey.Down=>((ushort)0x28,true),DesktopApprovedKey.Left=>((ushort)0x25,true),DesktopApprovedKey.Right=>((ushort)0x27,true),DesktopApprovedKey.BrowserBack=>((ushort)0xA6,true),DesktopApprovedKey.BrowserForward=>((ushort)0xA7,true),DesktopApprovedKey.MediaPlayPause=>((ushort)0xB3,true),DesktopApprovedKey.VolumeUp=>((ushort)0xAF,true),DesktopApprovedKey.VolumeDown=>((ushort)0xAE,true),DesktopApprovedKey.Mute=>((ushort)0xAD,true),DesktopApprovedKey.ShiftTab=>((ushort)0x09,false),_=>((ushort)0,false)};if(code==0)return new(false,"The key is not approved.");List<INPUT>inputs=[];if(key==DesktopApprovedKey.ShiftTab)inputs.Add(Key(0x10,false,false));inputs.Add(Key(code,false,extended));inputs.Add(Key(code,true,extended));if(key==DesktopApprovedKey.ShiftTab)inputs.Add(Key(0x10,true,false));return Send(inputs);}
    public void ReleaseAll(){Send([Mouse(0x0004,0),Mouse(0x0010,0),Mouse(0x0040,0)]);}
    private static INPUT Mouse(uint flags,int data)=>new(){Type=0,Union=new(){Mouse=new(){Flags=flags,MouseData=unchecked((uint)data)}}};private static INPUT Key(ushort code,bool up,bool extended)=>new(){Type=1,Union=new(){Keyboard=new(){VirtualKey=code,Flags=(uint)((up?2:0)|(extended?1:0))}}};private static DesktopInputInjectionResult Send(IReadOnlyCollection<INPUT>values){if(values.Count==0)return new(true,"No input required.");INPUT[] array=[..values];uint sent=SendInput((uint)array.Length,array,Marshal.SizeOf<INPUT>());return sent==array.Length?new(true,"Input injected."):Failure();}private static DesktopInputInjectionResult Failure(){int error=Marshal.GetLastWin32Error();return new(false,new Win32Exception(error).Message,error);}
    [LibraryImport("user32.dll",SetLastError=true)]private static partial uint SendInput(uint count,[In]INPUT[]inputs,int size);[LibraryImport("user32.dll",SetLastError=true)][return:MarshalAs(UnmanagedType.Bool)]private static partial bool GetCursorPos(out POINT point);[LibraryImport("user32.dll",SetLastError=true)][return:MarshalAs(UnmanagedType.Bool)]private static partial bool SetCursorPos(int x,int y);[LibraryImport("user32.dll")]private static partial int GetSystemMetrics(int index);
    [StructLayout(LayoutKind.Sequential)]private struct INPUT{public uint Type;public INPUTUNION Union;}[StructLayout(LayoutKind.Explicit)]private struct INPUTUNION{[FieldOffset(0)]public MOUSEINPUT Mouse;[FieldOffset(0)]public KEYBDINPUT Keyboard;}[StructLayout(LayoutKind.Sequential)]private struct MOUSEINPUT{public int Dx,Dy;public uint MouseData,Flags,Time;public nint ExtraInfo;}[StructLayout(LayoutKind.Sequential)]private struct KEYBDINPUT{public ushort VirtualKey,Scan;public uint Flags,Time;public nint ExtraInfo;}private struct POINT{public int X,Y;}
}
